  [("ruta", "camino que se recorrerá"), ("distancia", "cuántos kilómetros hay entre el inicio y el final"), ("velocidad media", "distancia recorrida dividida por el tiempo"), ("pausa", "momento de descanso durante la salida"), ("ciclovía", "vía exclusiva o separada para bicicletas")],
