  [("Ir al ritmo de la persona más rápida.", "Quien va más lento se agota o se queda atrás.", "El grupo avanza al ritmo de quien va más lento."), ("Salir sin agua porque «es corto».", "Podrías deshidratarte si hace calor.", "Lleva agua siempre.")],
